scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions: pairs (i, j) where i < j and values[i] > values[j]
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.gcd_of_list:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute GCD of all values in the list
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])

    return float(result)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod m
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.sum_floor_division:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute sum of floor divisions
    total = 0
    for i in range(len(A)):
        total += A[i] // B[i]

    return float(total)

